const sql = postgres(url, { ssl: "require", max: 1, onnotice: () => {} });
try {
  await sql.unsafe(readFileSync(file, "utf8"));
  console.log(`✓ ran ${file}`);
} catch (err) {
  console.error(`✗ ${file}: ${err.message}`);
  process.exitCode = 1;
} finally {
  await sql.end();
}

