import { db } from "./db";

export type SessionUser = { sub: string; email: string; name: string };

export async function currentUser(): Promise<SessionUser | null> {
  if (!auth0) return null;
  const user = (await auth0.getSession())?.user;
  if (!user?.sub || !isUwoEmail(user.email)) return null;
  return { sub: user.sub, email: user.email!, name: user.name ?? user.email!.split("@")[0] };
}

/** Common guard for account routes: DB configured + signed-in @uwo.ca user with a users row. */
export async function requireAccount() {
  const sql = db();
  if (!sql) return { error: NextResponse.json({ error: "db-unavailable", message: "Accounts aren't switched on yet." }, { status: 503 }) };
  const user = await currentUser();
  if (!user) return { error: NextResponse.json({ error: "signed-out", message: "Sign in with your @uwo.ca account." }, { status: 401 }) };
  const [row] = await sql<{ id: string; handle: string | null }[]>`SELECT id, handle FROM users WHERE auth0_id = ${user.sub}`;
  return { sql, user, me: row ?? null };
}

/** Lowercase handle from a display name: a-z 0-9 . _ - , 3–20 chars. */
export function toHandle(name: string) {
  const h = name
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^\w .-]/g, "")
    .trim()
    .replace(/\s+/g, ".")
    .replace(/[^a-z0-9._-]/g, "")
    .slice(0, 20);
  return h.length >= 3 ? h : `mustang${h}`.slice(0, 20);
}

export const isHandle = (h: unknown): h is string => typeof h === "string" && /^[a-z0-9._-]{3,24}$/.test(h);

import { NextResponse } from "next/server";
import { requireAccount, toHandle } from "@/lib/session";
import { fogRepFromCells } from "@/lib/rank";

const CELL = /^[0-9a-f]{15}$/;
const MAX_CELLS = 50_000;

type Body = {
  profile?: { name?: string; faculty?: string; year?: string; emblem?: string; accent?: string };
  cells?: string[];
  completions?: string[]; // mission slugs
};

/** Sync device progress to the account (idempotent). Returns the player's handle and server totals. */
export async function POST(req: Request) {
  const acc = await requireAccount();
  if ("error" in acc) return acc.error;
  const { sql, user } = acc;
  let me = acc.me;

  const body = (await req.json().catch(() => ({}))) as Body;
  const p = body.profile ?? {};
  const displayName = (p.name?.trim() || user.name).slice(0, 40);
  const accent = /^#[0-9a-fA-F]{6}$/.test(p.accent ?? "") ? p.accent! : "#FF4F8B";
  const emblem = /^[a-z]{3,12}$/.test(p.emblem ?? "") ? p.emblem! : "mustang";

  if (!me) {
    [me] = await sql<{ id: string; handle: string | null }[]>`
      INSERT INTO users (auth0_id, email, display_name) VALUES (${user.sub}, ${user.email}, ${displayName})
      ON CONFLICT (auth0_id) DO UPDATE SET email = EXCLUDED.email
      RETURNING id, handle`;
  }

  // Claim a unique handle once (from the display name), then keep it stable.
  let handle = me.handle;
  if (!handle) {
    const base = toHandle(displayName);
    const taken = new Set(
      (await sql<{ handle: string }[]>`SELECT handle FROM users WHERE handle LIKE ${base + "%"}`).map((r) => r.handle),
    );
    handle = base;
    for (let i = 2; taken.has(handle); i++) handle = `${base.slice(0, 17)}${i}`;
  }

  const cells = (body.cells ?? []).filter((c) => typeof c === "string" && CELL.test(c)).slice(0, MAX_CELLS);
  if (cells.length) {
    await sql`
      INSERT INTO revealed_cells (user_id, h3_cell)
      SELECT ${me.id}, c FROM unnest(${cells}::text[]) AS c
      ON CONFLICT (user_id, h3_cell) DO NOTHING`;
  }
  const slugs = (body.completions ?? []).filter((s) => typeof s === "string").slice(0, 200);
  if (slugs.length) {
    await sql`
      INSERT INTO mission_completions (mission_id, user_id, gemini_pass, gemini_reason)
      SELECT id, ${me.id}, true, 'Synced from device' FROM missions WHERE slug = ANY(${slugs}::text[])
      ON CONFLICT (mission_id, user_id) DO NOTHING`;
  }

  const [stats] = await sql<{ cells: number; missions: number; mission_rep: number }[]>`
    SELECT
      (SELECT count(*)::int FROM revealed_cells WHERE user_id = ${me.id}) AS cells,
      (SELECT count(*)::int FROM mission_completions WHERE user_id = ${me.id}) AS missions,
      (SELECT coalesce(sum(m.rep_reward), 0)::int FROM mission_completions mc JOIN missions m ON m.id = mc.mission_id
        WHERE mc.user_id = ${me.id}) AS mission_rep`;
  const rep = fogRepFromCells(stats.cells) + stats.mission_rep;

  await sql`
    UPDATE users SET handle = ${handle}, display_name = ${displayName}, faculty = ${p.faculty?.slice(0, 60) || null},
      year = ${p.year?.slice(0, 20) || null}, emblem = ${emblem}, accent = ${accent},
      explored_cells = ${stats.cells}, mission_count = ${stats.missions}, rep = ${rep}, updated_at = now()
    WHERE id = ${me.id}`;

  return NextResponse.json({ handle, rep, cells: stats.cells, missions: stats.missions });
}

import { NextResponse } from "next/server";
import { isHandle, requireAccount } from "@/lib/session";

export type FriendRow = {
  handle: string;
  name: string;
  faculty: string | null;
  year: string | null;
  emblem: string;
  accent: string;
  rep: number;
  cells: number;
  missions: number;
};

const COLS = `u.handle, u.display_name AS name, u.faculty, u.year, u.emblem, u.accent, u.rep,
  u.explored_cells AS cells, u.mission_count AS missions`;

/** Accepted friends + pending requests (incoming and outgoing). */
export async function GET() {
  const acc = await requireAccount();
  if ("error" in acc) return acc.error;
  const { sql, me } = acc;
  if (!me) return NextResponse.json({ friends: [], incoming: [], outgoing: [] });

  const rows = await sql.unsafe<(FriendRow & { kind: string })[]>(
    `SELECT 'friend' AS kind, ${COLS} FROM friendships f JOIN users u ON u.id = f.friend_id
       WHERE f.user_id = $1 AND f.status = 'accepted'
     UNION ALL
     SELECT 'incoming', ${COLS} FROM friendships f JOIN users u ON u.id = f.user_id
       WHERE f.friend_id = $1 AND f.status = 'pending'
     UNION ALL
     SELECT 'outgoing', ${COLS} FROM friendships f JOIN users u ON u.id = f.friend_id
       WHERE f.user_id = $1 AND f.status = 'pending'
     ORDER BY rep DESC`,
    [me.id],
  );
  const pick = (k: string) => rows.filter((r) => r.kind === k).map(({ kind: _kind, ...r }) => r);
  return NextResponse.json({ friends: pick("friend"), incoming: pick("incoming"), outgoing: pick("outgoing") });
}

/** Send a request by handle (or accept theirs if they already asked). */
export async function POST(req: Request) {
  const acc = await requireAccount();
  if ("error" in acc) return acc.error;
  const { sql, me } = acc;
  if (!me?.handle) return NextResponse.json({ error: "no-handle", message: "Open the app once signed in to claim your handle." }, { status: 409 });

  const { handle } = (await req.json().catch(() => ({}))) as { handle?: string };
  const h = handle?.trim().toLowerCase().replace(/^@/, "");
  if (!isHandle(h)) return NextResponse.json({ error: "bad-handle", message: "Handles are 3–20 letters, numbers, . _ or -" }, { status: 400 });
  if (h === me.handle) return NextResponse.json({ error: "self", message: "That's you. Find someone else." }, { status: 400 });

  const [target] = await sql<{ id: string }[]>`SELECT id FROM users WHERE handle = ${h}`;
  if (!target) return NextResponse.json({ error: "not-found", message: "No Mustang with that handle." }, { status: 404 });

  const [theirs] = await sql`SELECT status FROM friendships WHERE user_id = ${target.id} AND friend_id = ${me.id}`;
  if (theirs) {
    await accept(sql, me.id, target.id);
    return NextResponse.json({ status: "accepted" });
  }
  await sql`INSERT INTO friendships (user_id, friend_id, status) VALUES (${me.id}, ${target.id}, 'pending') ON CONFLICT DO NOTHING`;
  return NextResponse.json({ status: "pending" });
}

/** accept | decline | remove */
export async function PATCH(req: Request) {
  const acc = await requireAccount();
  if ("error" in acc) return acc.error;
  const { sql, me } = acc;
  if (!me) return NextResponse.json({ error: "no-account" }, { status: 409 });

  const { handle, action } = (await req.json().catch(() => ({}))) as { handle?: string; action?: string };
  if (!isHandle(handle)) return NextResponse.json({ error: "bad-handle" }, { status: 400 });
  const [other] = await sql<{ id: string }[]>`SELECT id FROM users WHERE handle = ${handle}`;
  if (!other) return NextResponse.json({ error: "not-found" }, { status: 404 });

  if (action === "accept") {
    const [req_] = await sql`SELECT 1 FROM friendships WHERE user_id = ${other.id} AND friend_id = ${me.id}`;
    if (!req_) return NextResponse.json({ error: "no-request" }, { status: 404 });
    await accept(sql, me.id, other.id);
  } else if (action === "decline" || action === "remove") {
    await sql`DELETE FROM friendships WHERE (user_id = ${me.id} AND friend_id = ${other.id}) OR (user_id = ${other.id} AND friend_id = ${me.id})`;
  } else {
    return NextResponse.json({ error: "bad-action" }, { status: 400 });
  }
  return NextResponse.json({ ok: true });
}

async function accept(sql: NonNullable<ReturnType<typeof import("@/lib/db").db>>, me: string, other: string) {
  await sql`
    INSERT INTO friendships (user_id, friend_id, status) VALUES (${other}, ${me}, 'accepted'), (${me}, ${other}, 'accepted')
    ON CONFLICT (user_id, friend_id) DO UPDATE SET status = 'accepted'`;
}

import { NextResponse } from "next/server";
import { isHandle, requireAccount } from "@/lib/session";

/** A friend's revealed cells — only for accepted friends (brief → privacy: revealed cells, never raw traces). */
export async function GET(_req: Request, { params }: { params: Promise<{ handle: string }> }) {
  const acc = await requireAccount();
  if ("error" in acc) return acc.error;
  const { sql, me } = acc;
  const { handle } = await params;
  if (!me || !isHandle(handle)) return NextResponse.json({ error: "bad-request" }, { status: 400 });

  const [friend] = await sql<{ id: string }[]>`
    SELECT u.id FROM users u JOIN friendships f ON f.friend_id = u.id
    WHERE u.handle = ${handle} AND f.user_id = ${me.id} AND f.status = 'accepted'`;
  if (!friend) return NextResponse.json({ error: "not-friends", message: "You can only see friends' maps." }, { status: 403 });

  const rows = await sql<{ h3_cell: string }[]>`SELECT h3_cell FROM revealed_cells WHERE user_id = ${friend.id} LIMIT 50000`;
  return NextResponse.json({ cells: rows.map((r) => r.h3_cell) });
}

"use client";
/**
 * Account state (Auth0 session as seen by the browser) + background sync of device progress.
 * Loaded once per app session; Profile and Crew read it from here.
 */
import { getCells, subscribe as subscribeFog } from "./fog";
import { getSnapshot as getProgress, subscribe as subscribeProgress } from "./progress";

export type User = { name?: string; email?: string; picture?: string };
export type AccountState = {
  auth: "loading" | "signed-in" | "signed-out" | "unavailable";
  user: User | null;
  handle: string | null;
  sync: "idle" | "syncing" | "ok" | "db-unavailable" | "error";
};

let state: AccountState = { auth: "loading", user: null, handle: null, sync: "idle" };
const listeners = new Set<() => void>();
let started = false;

function set(patch: Partial<AccountState>) {
  state = { ...state, ...patch };
  listeners.forEach((l) => l());
}

export const getAccount = () => state;
const SERVER: AccountState = { auth: "loading", user: null, handle: null, sync: "idle" };
export const getServerAccount = () => SERVER;

export function subscribeAccount(l: () => void) {
  start();
  listeners.add(l);
  return () => listeners.delete(l);
}

function start() {
  if (started || typeof window === "undefined") return;
  started = true;
  fetch("/auth/profile", { cache: "no-store" })
    .then(async (res) => {
      if (res.ok && res.status !== 204) {
        set({ auth: "signed-in", user: (await res.json()) as User });
        void syncNow();
        let timer: ReturnType<typeof setTimeout> | undefined;
        const schedule = () => {
          clearTimeout(timer);
          timer = setTimeout(() => void syncNow(), 15_000);
        };
        subscribeFog(schedule);
        subscribeProgress(schedule);
      } else if (res.status === 401 || res.status === 204) set({ auth: "signed-out" });
      else set({ auth: "unavailable" });
    })
    .catch(() => set({ auth: "unavailable" }));
}

/** Push profile, revealed cells and completions to the account. */
export async function syncNow() {
  if (state.auth !== "signed-in" || state.sync === "db-unavailable") return;
  set({ sync: "syncing" });
  const { profile, completions } = getProgress();
  try {
    const res = await fetch("/api/me", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        profile: { name: profile.name, faculty: profile.faculty, year: profile.year, emblem: profile.emblem, accent: profile.accent },
        cells: getCells(),
        completions: Object.keys(completions),
      }),
    });
    if (res.status === 503) return set({ sync: "db-unavailable" });
    if (!res.ok) return set({ sync: "error" });
    const json = (await res.json()) as { handle: string };
    set({ sync: "ok", handle: json.handle });
  } catch {
    set({ sync: "error" });
  }
}

/**
 * Demo crew: clearly labelled sample players shown only when real friends are unavailable
 * (signed out, or accounts not configured), so the comparison UI can be demoed. Never mixed with real friends.
 */
import { cellsAround } from "./fog";
import { densify, type LngLat } from "./geo";
import type { FriendRow } from "@/app/api/friends/route";

type Demo = FriendRow & { path: LngLat[] };

const DEMO: Demo[] = [
  {
    handle: "demo.maya",
    name: "Maya (demo)",
    faculty: "Science",
    year: "2nd year",
    emblem: "owl",
    accent: "#2EE6D6",
    rep: 1840,
    cells: 0,
    missions: 6,
    // campus → Richmond Row → downtown
    path: [[-81.2737, 43.0096], [-81.2655, 43.0055], [-81.2565, 42.9995], [-81.251, 42.9935], [-81.2485, 42.986]],
  },
  {
    handle: "demo.dev",
    name: "Dev (demo)",
    faculty: "Engineering",
    year: "1st year",
    emblem: "bolt",
    accent: "#FF8A3D",
    rep: 620,
    cells: 0,
    missions: 3,
    // engineering buildings → Masonville
    path: [[-81.2765, 43.0105], [-81.2765, 43.0175], [-81.2745, 43.0265], [-81.2735, 43.0255]],
  },
  {
    handle: "demo.jules",
    name: "Jules (demo)",
    faculty: "Social Science",
    year: "3rd year",
    emblem: "goose",
    accent: "#7B2FF7",
    rep: 5320,
    cells: 0,
    missions: 11,
    // Old East Village loop
    path: [[-81.2335, 42.9905], [-81.2255, 42.9895], [-81.2195, 42.9885], [-81.2215, 42.9845], [-81.2315, 42.9855]],
  },
];

const cache = new Map<string, string[]>();

export function demoCells(handle: string) {
  if (!cache.has(handle)) {
    const d = DEMO.find((x) => x.handle === handle);
    const set = new Set<string>();
    for (const [lng, lat] of densify(d?.path ?? [], 60)) for (const c of cellsAround(lat, lng, 110)) set.add(c);
    cache.set(handle, [...set]);
  }
  return cache.get(handle)!;
}

export function demoFriends(): FriendRow[] {
  return DEMO.map(({ path: _path, ...f }) => ({ ...f, cells: demoCells(f.handle).length }));
}

"use client";

import { useCallback, useEffect, useState, useSyncExternalStore } from "react";
import QRCode from "qrcode";
import { getAccount, getServerAccount, subscribeAccount, syncNow } from "@/lib/account";
import { getServerSnapshot, getSnapshot, subscribe } from "@/lib/progress";
import { pctFromCells } from "@/lib/fog";
import { rankFor, fogRepFromCells } from "@/lib/rank";
import { demoCells, demoFriends } from "@/lib/demoCrew";
import type { FriendRow } from "@/app/api/friends/route";
import type { EmblemId } from "@/lib/progress";
import Emblem from "../profile/Emblem";

type Lists = { friends: FriendRow[]; incoming: FriendRow[]; outgoing: FriendRow[] };
type Props = {
  prefill: string | null;
  shownFriend: string | null;
  onToggleMap: (friend: FriendRow, cells: string[] | null) => void;
};

const fmtPct = (p: number) => `${p < 10 ? p.toFixed(2) : p.toFixed(1)}%`;

export default function CrewPanel({ prefill, shownFriend, onToggleMap }: Props) {
  const account = useSyncExternalStore(subscribeAccount, getAccount, getServerAccount);
  const me = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
  const live = account.auth === "signed-in" && account.sync !== "db-unavailable";
  const [lists, setLists] = useState<Lists | null>(null);
  const [input, setInput] = useState(prefill ?? "");
  const [msg, setMsg] = useState<{ tone: "ok" | "err"; text: string } | null>(null);
  const [qr, setQr] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const load = useCallback(async () => {
    const res = await fetch("/api/friends", { cache: "no-store" });
    if (res.ok) setLists((await res.json()) as Lists);
  }, []);

  useEffect(() => {
    if (live && account.handle) void load();
  }, [live, account.handle, load]);

  const shareUrl = account.handle ? `${window.location.origin}/?add=${account.handle}` : null;

  async function toggleQr() {
    if (qr) return setQr(null);
    if (!shareUrl) return;
    setQr(await QRCode.toString(shareUrl, { type: "svg", margin: 1, color: { dark: "#140A2E", light: "#FFFFFF" } }));
  }

  async function add() {
    const handle = input.trim().toLowerCase().replace(/^@/, "");
    if (!handle) return;
    setBusy(true);
    setMsg(null);
    try {
      const res = await fetch("/api/friends", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ handle }) });
      const json = (await res.json()) as { status?: string; message?: string };
      if (!res.ok) setMsg({ tone: "err", text: json.message ?? "Couldn't add that handle." });
      else {
        setMsg({ tone: "ok", text: json.status === "accepted" ? `You and @${handle} are now crew.` : `Request sent to @${handle}.` });
        setInput("");
        await load();
      }
    } finally {
      setBusy(false);
    }
  }

  async function act(handle: string, action: "accept" | "decline" | "remove") {
    await fetch("/api/friends", { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ handle, action }) });
    if (action === "remove" && shownFriend === handle) onToggleMap({ handle } as FriendRow, null);
    await load();
  }

  async function toggleMap(f: FriendRow, demo: boolean) {
    if (shownFriend === f.handle) return onToggleMap(f, null);
    if (demo) return onToggleMap(f, demoCells(f.handle));
    const res = await fetch(`/api/friends/${f.handle}/cells`, { cache: "no-store" });
    if (res.ok) onToggleMap(f, ((await res.json()) as { cells: string[] }).cells);
  }

  const mine = { rep: me.rep, pct: me.pct, missions: me.missionCount };
  const h = "mb-2 text-[12px] font-bold tracking-[0.16em] text-ink/55 uppercase";
  const field = "min-w-0 flex-1 rounded-xl border border-white/12 bg-white/[0.06] px-3.5 py-3 text-[16px] text-ink outline-none focus:border-pink";

  return (
    <div className="space-y-6 pb-4">
      {live ? (
        <>
          <section className="rounded-3xl border border-white/10 bg-white/[0.04] p-4">
            <p className="text-[12px] font-bold tracking-[0.16em] text-ink/55 uppercase">Your handle</p>
            <div className="mt-1 flex items-center gap-3">
              <p className="min-w-0 flex-1 truncate text-[22px] font-bold text-ink">{account.handle ? `@${account.handle}` : "Claiming…"}</p>
              {account.handle && (
                <button type="button" onClick={toggleQr} className="min-h-[40px] rounded-full bg-white/10 px-4 text-[13px] font-bold text-ink">
                  {qr ? "Hide QR" : "QR code"}
                </button>
              )}
            </div>
            {qr && (
              <div className="mt-3 flex flex-col items-center gap-2">
                <div className="w-48 overflow-hidden rounded-2xl bg-white p-2" dangerouslySetInnerHTML={{ __html: qr }} />
                <p className="text-[12px] text-ink/60">Friends scan this to add you</p>
              </div>
            )}
          </section>

          <section>
            <h3 className={h}>Add crew</h3>
            <form
              className="flex gap-2"
              onSubmit={(e) => {
                e.preventDefault();
                void add();
              }}
            >
              <input
                className={field}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="@handle"
                autoCapitalize="none"
                autoCorrect="off"
                spellCheck={false}
              />
              <button type="submit" disabled={busy || !input.trim()} className="min-h-[50px] rounded-xl bg-pink px-5 text-[15px] font-bold text-night disabled:opacity-40">
                Add
              </button>
            </form>
            {msg && <p className={`mt-2 text-[13px] ${msg.tone === "ok" ? "text-teal" : "text-pink"}`} role="status">{msg.text}</p>}
          </section>

          {lists && lists.incoming.length > 0 && (
            <section>
              <h3 className={h}>Requests</h3>
              <ul className="space-y-2">
                {lists.incoming.map((f) => (
                  <li key={f.handle} className="flex items-center gap-3 rounded-2xl bg-white/[0.05] p-3">
                    <Emblem id={f.emblem as EmblemId} accent={f.accent} size={40} />
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-[15px] font-bold text-ink">{f.name}</p>
                      <p className="truncate text-[12px] text-ink/55">@{f.handle}</p>
                    </div>
                    <button type="button" onClick={() => act(f.handle, "accept")} className="min-h-[40px] rounded-full bg-teal px-4 text-[13px] font-bold text-night">
                      Accept
                    </button>
                    <button type="button" onClick={() => act(f.handle, "decline")} aria-label={`Decline ${f.name}`} className="min-h-[40px] min-w-[40px] rounded-full bg-white/10 text-[15px] text-ink/70">
                      ✕
                    </button>
                  </li>
                ))}
              </ul>
            </section>
          )}

          <section>
            <h3 className={h}>Crew</h3>
            {!lists ? (
              <div className="h-20 animate-pulse rounded-2xl bg-white/5" />
            ) : lists.friends.length === 0 ? (
              <p className="text-[14px] text-ink/60">
                No crew yet. Share your QR code or add a friend by handle.
                {lists.outgoing.length > 0 && ` Waiting on ${lists.outgoing.map((o) => "@" + o.handle).join(", ")}.`}
              </p>
            ) : (
              <ul className="space-y-3">
                {lists.friends.map((f) => (
                  <FriendCard key={f.handle} f={f} mine={mine} shown={shownFriend === f.handle} onMap={() => toggleMap(f, false)} onRemove={() => act(f.handle, "remove")} />
                ))}
              </ul>
            )}
          </section>
        </>
      ) : (
        <>
          <section className="rounded-3xl border border-pink/30 bg-pink/10 p-4">
            <p className="text-[15px] font-bold text-ink">
              {account.auth === "loading" ? "Checking your account…" : account.auth === "signed-out" ? "Sign in to build your crew" : "Crews aren't switched on yet"}
            </p>
            <p className="mt-1 text-[13px] leading-snug text-ink/70">
              Add Western friends by handle or QR, compare Rep and % explored, and see the parts of Forest State they&apos;ve uncovered.
            </p>
            {account.auth === "signed-out" && (
              <a href="/auth/login" className="mt-3 flex min-h-[48px] items-center justify-center rounded-2xl bg-pink text-[15px] font-bold text-night uppercase">
                Sign in with @uwo.ca
              </a>
            )}
            {account.auth === "signed-in" && account.sync === "db-unavailable" && (
              <button type="button" onClick={() => void syncNow()} className="mt-3 text-[13px] font-semibold text-teal underline">
                Retry
              </button>
            )}
          </section>
          <section>
            <h3 className={h}>Demo crew</h3>
            <p className="-mt-1 mb-2 text-[12px] text-ink/50">Sample players so you can try comparing. Not real accounts.</p>
            <ul className="space-y-3">
              {demoFriends().map((f) => (
                <FriendCard key={f.handle} f={f} mine={mine} shown={shownFriend === f.handle} onMap={() => toggleMap(f, true)} demo />
              ))}
            </ul>
          </section>
        </>
      )}
    </div>
  );
}

function FriendCard({
  f,
  mine,
  shown,
  onMap,
  onRemove,
  demo = false,
}: {
  f: FriendRow;
  mine: { rep: number; pct: number; missions: number };
  shown: boolean;
  onMap: () => void;
  onRemove?: () => void;
  demo?: boolean;
}) {
  // Demo players have a fixed Rep story; real friends' Rep comes from the server.
  const theirRep = demo ? Math.max(f.rep, fogRepFromCells(f.cells)) : f.rep;
  const theirs = { rep: theirRep, pct: pctFromCells(f.cells), missions: f.missions };
  const rows: { label: string; you: number; them: number; fmt: (n: number) => string }[] = [
    { label: "Rep", you: mine.rep, them: theirs.rep, fmt: (n) => n.toLocaleString() },
    { label: "Explored", you: mine.pct, them: theirs.pct, fmt: fmtPct },
    { label: "Missions", you: mine.missions, them: theirs.missions, fmt: (n) => String(n) },
  ];
  return (
    <li className="rounded-3xl border border-white/10 bg-white/[0.04] p-4">
      <div className="flex items-center gap-3">
        <Emblem id={f.emblem as EmblemId} accent={f.accent} size={48} />
        <div className="min-w-0 flex-1">
          <p className="truncate text-[16px] font-bold text-ink">{f.name}</p>
          <p className="truncate text-[12px] text-ink/55">
            {rankFor(theirs.rep).rank}
            {f.faculty ? ` · ${f.faculty}` : ""}
          </p>
        </div>
        {onRemove && (
          <button type="button" onClick={onRemove} className="text-[12px] font-semibold text-ink/40 underline">
            Remove
          </button>
        )}
      </div>

      <div className="mt-3 space-y-2">
        <div className="flex justify-between text-[11px] font-bold tracking-[0.12em] text-ink/45 uppercase">
          <span>You</span>
          <span>{f.name.split(" ")[0]}</span>
        </div>
        {rows.map((r) => {
          const total = r.you + r.them || 1;
          return (
            <div key={r.label}>
              <div className="flex justify-between text-[13px] tabular-nums">
                <span className={r.you >= r.them ? "font-bold text-ink" : "text-ink/60"}>{r.fmt(r.you)}</span>
                <span className="text-[11px] text-ink/45 uppercase">{r.label}</span>
                <span className={r.them > r.you ? "font-bold text-ink" : "text-ink/60"}>{r.fmt(r.them)}</span>
              </div>
              <div className="mt-1 flex h-1.5 overflow-hidden rounded-full bg-white/10">
                <div className="h-full bg-pink" style={{ width: `${(r.you / total) * 100}%` }} />
                <div className="h-full" style={{ width: `${(r.them / total) * 100}%`, background: f.accent }} />
              </div>
            </div>
          );
        })}
      </div>

      <button
        type="button"
        onClick={onMap}
        className="mt-3 flex min-h-[44px] w-full items-center justify-center rounded-2xl text-[14px] font-bold"
        style={shown ? { background: f.accent, color: "#140A2E" } : { background: "rgba(255,255,255,0.07)", color: "#F6EFFF" }}
      >
        {shown ? "Hide their map" : "Show their map"}
      </button>
    </li>
  );
}

