"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { onFix } from "@/lib/location";
import { districtAt } from "@/lib/districts";

/** Open-world style area title: the district name fades in when the player crosses into it. */
export default function AreaBanner() {
  const [area, setArea] = useState<string | null>(null);
  const last = useRef<string | null | undefined>(undefined);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  useEffect(() => {
    let lastCheck = 0;
    const off = onFix((fix) => {
      const now = performance.now();
      if (now - lastCheck < 800) return; // point-in-polygon at most ~once a second
      lastCheck = now;
      const name = districtAt(fix.lngLat);
      if (name === last.current) return;
      const first = last.current === undefined;
      last.current = name;
      if (!name || first) return; // no banner on the very first fix of the session
      setArea(name);
      clearTimeout(timer.current);
      timer.current = setTimeout(() => setArea(null), 2800);
    });
    return () => {
      off();
      clearTimeout(timer.current);
    };
  }, []);

  return (
    <AnimatePresence>
      {area && (
        <motion.div
          key={area}
          className="pointer-events-none absolute inset-x-0 z-20 text-center"
          style={{ top: "calc(var(--safe-top) + 92px)" }}
          initial={{ opacity: 0, y: -8, letterSpacing: "0.5em" }}
          animate={{ opacity: 1, y: 0, letterSpacing: "0.22em" }}
          exit={{ opacity: 0 }}
          transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1] }}
        >
          <p className="text-[11px] font-bold tracking-[0.3em] text-teal/90 uppercase drop-shadow">Entering</p>
          <p className="font-display text-[30px] leading-tight text-ink uppercase drop-shadow-[0_3px_14px_rgba(0,0,0,0.9)]">{area}</p>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

"use client";

import { useState, useSyncExternalStore } from "react";
import { DISTRICTS, UNLOCK_SHARE, getDistrictStats, subscribeDistricts } from "@/lib/districts";
import type { ProgressSnapshot } from "@/lib/progress";

const noStats = () => [];

/** Profile → Neighbourhoods: unlocked count + progress toward 30% in each district. */
export default function Neighbourhoods({ snap }: { snap: ProgressSnapshot }) {
  const stats = useSyncExternalStore(subscribeDistricts, getDistrictStats, noStats);
  const [all, setAll] = useState(false);
  const unlocked = Object.keys(snap.districts).length;
  const rows = [...stats].sort((a, b) => Number(!!snap.districts[b.name]) - Number(!!snap.districts[a.name]) || b.pct - a.pct);
  const shown = all ? rows : rows.filter((r) => r.have > 0 || snap.districts[r.name]).slice(0, 6);

  return (
    <section>
      <h3 className="mb-2 text-[12px] font-bold tracking-[0.16em] text-ink/55 uppercase">
        Neighbourhoods · {unlocked}/{DISTRICTS.length}
      </h3>
      {shown.length === 0 ? (
        <p className="text-[14px] text-ink/60">Explore {Math.round(UNLOCK_SHARE * 100)}% of a neighbourhood to unlock it.</p>
      ) : (
        <ul className="space-y-2">
          {shown.map((r) => {
            const done = !!snap.districts[r.name];
            const toUnlock = Math.min(1, r.pct / UNLOCK_SHARE);
            return (
              <li key={r.name} className="rounded-2xl bg-white/[0.04] px-3 py-2.5">
                <div className="flex items-baseline justify-between">
                  <span className={`text-[14px] font-semibold ${done ? "text-gold" : "text-ink"}`}>{r.name}</span>
                  <span className="text-[12px] text-ink/55 tabular-nums">{done ? "Unlocked" : `${Math.round(r.pct * 100)}% / 30%`}</span>
                </div>
                <div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-white/10">
                  <div className={`h-full rounded-full ${done ? "bg-gold" : "bg-teal"}`} style={{ width: `${(done ? 1 : toUnlock) * 100}%` }} />
                </div>
              </li>
            );
          })}
        </ul>
      )}
      <button type="button" onClick={() => setAll((a) => !a)} className="mt-2 text-[12px] font-semibold text-teal underline">
        {all ? "Show fewer" : `Show all ${DISTRICTS.length}`}
      </button>
      <p className="mt-1 text-[10px] text-ink/35">Boundaries: City of London Open Data (Planning Districts)</p>
    </section>
  );
}

