import { NextResponse } from "next/server";
import { latLngToCell } from "h3-js";
import { requireAccount } from "@/lib/session";
import { H3_RES } from "@/lib/fog";

type Ping = { ts: number; lat: number; lng: number; acc: number };
const MAX_BATCH = 500;

/**
 * Batch-insert live GPS fixes into the `location_pings` hypertable (brief → Data model).
 * Feeds replay/Wrapped across devices and the `user_daily_cells` continuous aggregate.
 */
export async function POST(req: Request) {
  const acc = await requireAccount();
  if ("error" in acc) return acc.error;
  const { sql, me } = acc;
  if (!me) return NextResponse.json({ error: "no-account", message: "Sync your profile first." }, { status: 409 });

  const body = (await req.json().catch(() => ({}))) as { pings?: Ping[] };
  const now = Date.now();
  const pings = (body.pings ?? [])
    .filter(
      (p) =>
        Number.isFinite(p.ts) && p.ts > now - 7 * 864e5 && p.ts < now + 6e4 && // last week, not the future
        Math.abs(p.lat) <= 90 && Math.abs(p.lng) <= 180 && Number.isFinite(p.acc) && p.acc >= 0 && p.acc < 5000,
    )
    .slice(0, MAX_BATCH);
  if (!pings.length) return NextResponse.json({ inserted: 0 });

  const ts = pings.map((p) => new Date(p.ts).toISOString());
  const lat = pings.map((p) => p.lat);
  const lng = pings.map((p) => p.lng);
  const accuracy = pings.map((p) => Math.round(p.acc));
  const cells = pings.map((p) => latLngToCell(p.lat, p.lng, H3_RES));

  await sql`
    INSERT INTO location_pings (user_id, ts, lat, lng, accuracy_m, h3_cell)
    SELECT ${me.id}, t::timestamptz, la, ln, a, c
    FROM unnest(${ts}::text[], ${lat}::float8[], ${lng}::float8[], ${accuracy}::real[], ${cells}::text[]) AS x(t, la, ln, a, c)`;

  return NextResponse.json({ inserted: pings.length });
}

"use client";
/**
 * Buffers real GPS fixes and sends them to /api/pings in batches while signed in.
 * Stops quietly for the session when accounts/DB aren't available (503/401).
 */
import { onFix } from "./location";
import { getAccount, subscribeAccount } from "./account";

const FLUSH_MS = 30_000;
const FLUSH_AT = 25;
const MAX_BUFFER = 2000;

type Ping = { ts: number; lat: number; lng: number; acc: number };
let buffer: Ping[] = [];
let started = false;
let disabled = false;
let timer: ReturnType<typeof setInterval> | undefined;
let inflight = false;

async function flush() {
  if (disabled || inflight || !buffer.length) return;
  const { auth, sync } = getAccount();
  if (auth !== "signed-in" || sync === "db-unavailable") return;
  inflight = true;
  const batch = buffer.slice(0, 500);
  try {
    const res = await fetch("/api/pings", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ pings: batch }),
      keepalive: true,
    });
    if (res.ok) buffer = buffer.slice(batch.length);
    else if (res.status === 503 || res.status === 401) {
      disabled = true; // accounts off or signed out: keep the device-only replay, stop trying
      buffer = [];
    }
    // 409 (profile not synced yet) or 5xx: keep the buffer and retry next tick
  } catch {
    /* offline — retry next tick */
  } finally {
    inflight = false;
  }
}

export function startPingLog() {
  if (started || typeof window === "undefined") return;
  started = true;
  subscribeAccount(() => {});
  onFix((fix) => {
    if (fix.source !== "gps" || disabled || getAccount().auth === "signed-out" || getAccount().auth === "unavailable") return;
    buffer.push({ ts: fix.ts, lat: fix.lngLat[1], lng: fix.lngLat[0], acc: fix.accuracy });
    if (buffer.length > MAX_BUFFER) buffer = buffer.slice(-MAX_BUFFER);
    if (buffer.length >= FLUSH_AT) void flush();
  });
  timer = setInterval(() => void flush(), FLUSH_MS);
  window.addEventListener("pagehide", () => void flush());
}

export const _pingLogTimer = () => timer; // for tests/debugging

